import base64,json,html
from pathlib import Path
p=Path(__file__).parent
def data(f):return 'data:image/'+('webp' if f.suffix=='.webp' else 'png')+';base64,'+base64.b64encode(f.read_bytes()).decode()
def icon(key,size=20):
    return '<span class="symbol" style="--size:'+str(size)+'px"><img src="'+data(p/'symbols'/('set-'+key+'-decipher.webp'))+'" alt="'+({'jabbaspalace':"Jabba’s Palace",'ds2':'Death Star II','reflections3':'Reflections III'}.get(key,key.title()))+' icon"></span>'
items=[('jabbaspalace',"Jabba’s Palace",'Jabbas-Palace'),('hoth','Hoth','Hoth'),('ds2','Death Star II','Death-Star-II'),('tatooine','Tatooine','Tatooine'),('reflections3','Reflections III',None)]
rows=''
for key,label,old in items:
    oldimg='<img width="20" height="20" src="'+data(p/'old-wiki-assets'/('Icon-set-'+old+'.png'))+'" alt="Current '+label+' icon">' if old else 'No current Icon-set file'
    rows+='<tr><th>'+label+'</th><td>'+oldimg+'</td>'+''.join('<td class="'+bg+'">'+icon(key)+' <span>'+label+'</span></td>' for bg in ['light','dark','checker'])+'<td>'+icon(key,64)+'</td></tr>'
def sentence(mode):
    marker={'image':icon('jabbaspalace'),'words':'<span class="icon-words">[Jabba’s Palace icon]</span>','both':icon('jabbaspalace')+' <span class="icon-words">[Jabba’s Palace icon]</span>'}[mode]
    return 'Deploy on table. Once during each of your turns, may deploy one Underworld Contacts, '+marker+' Lando, '+marker+' Leia, R2-D2, or C-3PO from Reserve Deck; reshuffle. Also, while Luke is at a Jabba’s Palace site, opponent’s aliens there must use +1 Force to use their landspeed.'
cards=''.join('<section class="choice"><h3>'+label+'</h3><p id="'+mode+'-sample">'+sentence(mode)+'</p></section>' for mode,label in [('image','A · Symbols only'),('words','B · Words only'),('both','C · Symbols + words')])
sources=json.loads((p/'symbols/manifest.json').read_bytes());sourcebytes=sum(x['bytes'] for x in sources['symbols'])
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared set symbols — Story435 visual test</title><style>
*{box-sizing:border-box}body{font:16px/1.55 system-ui,sans-serif;color:#202831;background:#f4f6f8;margin:0}main{max-width:1150px;margin:auto;padding:28px}h1{font-size:29px}h2{margin-top:32px}p{max-width:85ch}.note{border-left:4px solid #427a91;padding:12px 18px;background:#e5eef3}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:750px}th,td{text-align:left;border:1px solid #b8c0c8;padding:15px;vertical-align:middle}.light{background:#e4e8ec}.dark{background:#232b35;color:#fff}.checker{background:repeating-conic-gradient(#ddd 0% 25%,#fff 0% 50%) 0/16px 16px}.symbol{display:inline-flex;align-items:center;justify-content:center;width:var(--size);height:var(--size);vertical-align:-.2em;border:calc(var(--size)*.08) solid #111;border-radius:50%;overflow:hidden;background:#111;box-sizing:border-box;flex-shrink:0}.symbol img{display:block;width:100%;height:100%;border-radius:50%;object-fit:contain}.choices{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.choice{padding:18px;border:1px solid #b8c0c8;border-radius:8px;background:#e4e8ec}.choice h3{font-size:18px;margin-top:0}.icon-words{color:#315a73}.source{font-size:13px;color:#586572}code{background:#e7eaed;padding:2px 4px}.original{display:flex;gap:25px;flex-wrap:wrap;align-items:center}.original img{width:185px;height:auto}button{font:inherit;padding:7px 13px;cursor:pointer;border:1px solid #6f8190;border-radius:4px;background:#fff}#search-result{font-weight:600}@media(max-width:800px){main{padding:16px}.choices{grid-template-columns:1fr}}
</style><main><h1>Shared set symbols: visual test</h1><p class="note">Test candidates from CardMaker’s existing printed-sphere masters. The Wiki has not been migrated. Original PNG artwork is retained; WebP exports are reproducible. Regular Coruscant silver and AI gold variants remain separate verification work.</p><h2>Infobox: symbol + searchable set name</h2><p>Actual symbol size is20px. The last column is an enlarged inspection view. The black ring uses CardMaker’s existing inline recipe; red card-background fragments and white squares are outside the exported symbol.</p><div class="table-wrap"><table><thead><tr><th>Set</th><th>Current Wiki</th><th>Wiki background</th><th>Dark background</th><th>Transparency check</th><th>Enlarged</th></tr></thead><tbody>'''+rows+'''<tr><th>Premiere</th><td colspan="5">None (Premiere) — no symbol</td></tr></tbody></table></div><h2>Card text: compare all three choices</h2><p>The example is Seeking An Audience. These are presentation candidates for the same symbol references, not changes to the card’s rules. My recommendation is B for reading/searching, with the scan beside it; C is available if you want the printed symbol repeated in the transcription.</p><div class="choices">'''+cards+'''</div><p><button id="search-check" type="button">Check visible search wording</button> <span id="search-result"></span></p><h2>Printed-card reference</h2><div class="original"><img src="data:image/gif;base64,'''+base64.b64encode(Path('work/foil-display-fixes/samples/0').read_bytes()).decode()+'''" alt="Original printed Seeking An Audience card"><p>The symbol is at the right end of the lore box and appears twice in game text. Compare it with the shared Jabba’s Palace symbol above. The card photograph itself is unchanged.</p></div><h2>Shared source and limits</h2><p>''' +str(len(sources['symbols']))+' transparent96px WebP exports; '+str(sourcebytes)+''' bytes in total. Existing CardMaker PNG masters are the common source. The exporter checks alpha, unchanged masters and a lossless WebP round trip of each display resize.</p><p>CardMaker’s newer sphere cuts supersede older wiki-disc crops and Game Aid redraws. The complete source records remain in CardMaker. Coruscant regular/AI rings, other AI rings, and numbered Original/Legacy/Modern marks need their own print-verified inventory before broad replacement. Story286 retains wider missing-infobox coverage.</p><p class="source">Story435 · master commit a41df94fc32c197757650f03ae64f6c096342124 · no Archive.org/web.archive.org requests · no card-page migration in this test</p></main><script>document.querySelector('#search-check').onclick=()=>{let ids=['image','words','both'];document.querySelector('#search-result').textContent=ids.map((id,i)=>String.fromCharCode(65+i)+': '+(document.querySelector('#'+id+'-sample').innerText.includes('[Jabba’s Palace icon]')?'explicit searchable label':'no explicit symbol label')).join(' · ')};</script></html>'''
(p/'preview.html').write_text(doc,encoding='utf8');print('Self-contained symbol and search-presentation test written')
